!function(e){function n(n){for(var t,a,p=n[0],o=n[1],c=n[2],s=0,_=[];s<p.length;s++)a=p[s],Object.prototype.hasOwnProperty.call(i,a)&&i[a]&&_.push(i[a][0]),i[a]=0;for(t in o)Object.prototype.hasOwnProperty.call(o,t)&&(e[t]=o[t]);for(d&&d(n);_.length;)_.shift()();return m.push.apply(m,c||[]),r()}function r(){for(var e,n=0;n<m.length;n++){for(var r,a=m[n],p=!0,o=1;o<a.length;o++)r=a[o],0!==i[r]&&(p=!1);p&&(m.splice(n--,1),e=t(t.s=a[0]))}return e}function t(n){if(a[n])return a[n].exports;var r=a[n]={i:n,l:!1,exports:{}};return e[n].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var a={},i={34:0},m=[];t.m=e,t.c=a,t.d=function(e,n,r){t.o(e,n)||Object.defineProperty(e,n,{enumerable:!0,get:r})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,n){if(1&n&&(e=t(e)),8&n)return e;if(4&n&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&n&&"string"!=typeof e)for(var a in e)t.d(r,a,function(n){return e[n]}.bind(null,a));return r},t.n=function(e){var n=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(n,"a",n),n},t.o=function(e,n){return Object.prototype.hasOwnProperty.call(e,n)},t.p="";var p=window.webpackJsonp=window.webpackJsonp||[],o=p.push.bind(p);p.push=n,p=p.slice();for(var c=0;c<p.length;c++)n(p[c]);var d=o;m.push([216,0]),r()}({216:function(e,n,r){"use strict";r.r(n);var t=r(0);Object(t.a)("de","army",r(217),r(1))},217:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"火炮","link":"de_army#de_army_cannon"}],"model":"42型150mm车载火箭炮","description":"<p>1943年，德军将42型150mm双排式火箭炮安装在Sd.Kfz 4/1半履带装甲车上，成为一种车载火箭炮。该车载火箭炮经战场检验显示了极好的机动性与较强的战斗威力，于1944年5月全面装备给一线部队。</p><p>42型150mm车载火箭炮分上下两排，每排5个发射管，共10个发射管，发射管使用的是N41型150mm火箭炮的炮管，通过转台安装在半履带车后部；火箭炮的点火线在炮架两侧穿入到半履带车内部，由车内炮兵负责点火发射；此外，炮座下还加装了一个35型光学瞄准仪，大大提高了射击的准确率。</p><p>装备42型150mm车载火箭炮的部队由集团军或军一级直接指挥，为独立火箭炮连建制，每连下属两个排，每个排装备4门车载42型150mm火箭炮，每个排都是可以独立作战的。战场上，德军都会集中多门车载火箭炮进行作战，用猛烈而密集的火力来打击对手。车载火箭炮具有良好机动性，使其成为二战后期德军在战场上一种能快速机动的有效支援火力。</p><p>由于42型150mm车载火箭炮的装配数量受Sd.Kfz 4/1半履带装甲车的生产制约，而该型载车在1943至1944年间产量不足300辆（配有数量相近的的弹药车），所以德军实际装备数量并不多，一直难以满足德军在战场上的需求。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_cannon42150_11.jpg","description":"<h6>42型150mm车载火箭炮</h6><p></p><p>技术数据：</p><p>口径：150mm；</p><p>炮管长：1.3米；发射管数量：10根（上下两排，每排5根）；</p><p>转台左右旋转角度：270度；俯仰角：-12～+80度；</p><p>最大射程：6900米。</p>","caption":""},{"image":"imgs/de/army/de_army_cannon42150_12.jpg","description":"<p>装载42型150mm火箭炮的Sd.Kfz 4/1半履带装甲车</p><p>（详见“<a href=\\"de_army_avhtv2511&Kfz4.html\\">251/1、Sd.Kfz 4/1型半履带装甲火箭炮车”</a>）</p><p>Sd.Kfz 4/1半履带装甲车最高时速为40公里/小时；车体装甲厚8毫米，驾驶室与火箭炮座装甲厚10毫米；能爬12度坡；涉水深度0.44米。</p>","caption":""}],"part2title":"战场上的42型150mm车载火箭炮","part2description":"","part2content":[{"image":"imgs/de/army/de_army_cannon42150_21.jpg","description":"一门德军42型150mm车载火箭炮，图中可见火箭炮在车上是可以多方向射击的，由于是车载，因而可实现打了就跑的战术，其机动性和灵活性比牵引式火箭炮大大增强，生存机率也得以提高不少。","caption":""},{"image":"imgs/de/army/de_army_cannon42150_22.jpg","description":"1943年，正在接受检阅的德军42型150mm车载火箭炮。","caption":""},{"image":"imgs/de/army/de_army_cannon42150_23.jpg","description":"1943年，东线苏联战场，德军一辆42型150mm车载火箭炮车正在向库尔斯克前线开进。此时，该型火箭炮刚刚少量装备德军，正在接受战场检验。","caption":""},{"image":"imgs/de/army/de_army_cannon42150_24.jpg","description":"二战东线苏联战场，时值冬季，德军一辆42型150mm车载火箭炮车正在冒着风雪行进，车长打开上舱门探出身子观察路况，车头是一挺自卫用的MG34机枪。","caption":""},{"image":"imgs/de/army/de_army_cannon42150_25.jpg","description":"（图1）战斗时，42型150mm车载火箭炮的火箭弹都会先从车内拿出堆放在地面上，以方便火箭弹的运送装填。（图2）装填时，至少要2人合作，先将火箭弹从地上传送给车上的人，再由车上的人将火箭弹装填进火箭炮发射管中。注：每个火箭炮连的弹药基数为400枚，其中10%是烟雾弹，按每连有8门车载火箭炮，即每门炮都可分配50枚，其中20枚会装在装甲车内随车而行，其它会由弹药车运送。","caption":""},{"image":"imgs/de/army/de_army_cannon42150_26.jpg","description":"两名德军炮手正在半履带装甲车上准备进行42型150mm车载火箭炮的火箭弹装填，每门火箭炮随车的火箭弹基数为2次齐射所需的20枚火箭弹。","caption":""},{"image":"imgs/de/army/de_army_cannon42150_27.jpg","description":"1943～1944年冬季，东线战场，德军火箭炮排的三门42型150mm车载火箭炮正在阵地上作战斗准备。","caption":""},{"image":"imgs/de/army/de_army_cannon42150_28.jpg","description":"战斗命令响起，阵地上的德军炮兵快步奔向42型150mm车载火箭炮，该炮的火箭弹已经装填好，只待炮兵一到位则即可发射。炮车车身上的“C”字是表示该炮在连阵地中的位置。","caption":""},{"image":"imgs/de/army/de_army_cannon42150_29.jpg","description":"1943年，东线苏联战场，在库尔斯克前线的德军一门正在射击的42型150mm车载火箭炮。火箭弹出膛初速为340米/秒，图中可见火箭弹射出的状态。注：火箭炮的发射速度取决于火箭弹的装填速度，一般可在12秒内可完成一次齐射，在5分钟内完成3次齐射。","caption":""},{"image":"imgs/de/army/de_army_cannon42150_30.jpg","description":"正在夜间作战的德军一门42型150mm车载火箭炮，由于夜间火箭弹发射时的光柱非常显眼，很容易就会被对手发现火箭炮的位置，所以发射后炮车会迅速转移阵地。","caption":""},{"image":"imgs/de/army/de_army_cannon42150_31.jpg","description":"西线意大利战场，两名英军正在检查一门被德军遗弃的42型150mm车载火箭炮。","caption":""}]}')}});